    let last_gap = " ns".len() + GAP.len() + last_w;
    let count_gap = " ns".len() + GAP.len() + count_w;
    let mean_gap = GAP.len() + mean_w;
    let adj_gap = " ns".len() + GAP.len() + adj_w;
    println!(
        "{:>first_col$}{:>last_gap$}{:>count_gap$}{:>mean_gap$}{:>adj_gap$}",
        "first", "last", "count", "mean", "adjusted",
    );

    for r in &rows {
        println!(
            "{INDENT}{:<label_w$} {:>first_w$} ns{GAP}{:>last_w$} ns{GAP}{:>count_w$}{GAP}{:>mean_w$} ns{GAP}{:>adj_w$} ns",
            r.label, r.first, r.last, r.count, r.mean, r.adj_mean,
        );
    }

    // Whole-histogram summary. Aligned to mean/adjusted columns.
    let hist_mean = hist.mean();
    let hist_adj = (hist_mean - adj).max(0.0);
    let skip = first_w + " ns".len() + GAP.len() + last_w + " ns".len() + GAP.len() + count_w;
    println!(
        "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns{GAP}{:>adj_w$} ns",
        "mean",
        "",
        fmt_commas_f64(hist_mean, 0),
        fmt_commas_f64(hist_adj, 0),
    );
    println!(
        "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
        "stdev",
        "",
        fmt_commas_f64(hist.stdev(), 0),
    );
    println!();
}

use std::hint::black_box;
use std::sync::mpsc;
use std::thread;

use crate::harness::{self, Bench, RunCfg};
use crate::pin;

pub const NAME: &str = "mpsc-2t";

pub struct StdMpsc2Thread {
    req_tx: mpsc::Sender<u64>,
    resp_rx: mpsc::Receiver<u64>,
    worker: Option<thread::JoinHandle<()>>,
    counter: u64,
}

impl StdMpsc2Thread {
    pub fn new(worker_cpu: Option<usize>) -> Self {
        let (req_tx, req_rx) = mpsc::channel::<u64>();
        let (resp_tx, resp_rx) = mpsc::channel::<u64>();
        let worker = thread::spawn(move || {
            pin::pin_current(worker_cpu);
            while let Ok(v) = req_rx.recv() {
                if resp_tx.send(v).is_err() {
                    break;
                }
            }
        });
        Self {
            req_tx,
            resp_rx,
            worker: Some(worker),
            counter: 0,
        }
    }
}

impl Bench for StdMpsc2Thread {
    fn name(&self) -> &str {
        "std::sync::mpsc round-trip (2 threads)"
    }

    fn step(&mut self) -> u64 {
        self.counter = self.counter.wrapping_add(1);
        self.req_tx.send(self.counter).unwrap();
        let v = self.resp_rx.recv().unwrap();
        black_box(v)
    }
}

impl Drop for StdMpsc2Thread {
    fn drop(&mut self) {
        // Replace req_tx with a dummy so we can drop the real one;
        // worker's recv() then returns Err and the worker exits.
        // Done this way (instead of Option<Sender>) to keep step() branch-free.
        let (dummy_tx, _) = mpsc::channel();
        drop(std::mem::replace(&mut self.req_tx, dummy_tx));
        if let Some(worker) = self.worker.take() {
            let _ = worker.join();
        }
    }
}

pub fn run(cfg: &RunCfg) {
    let mut bench = StdMpsc2Thread::new(cfg.core_for(1));
    let (hist, iterations, inner, duration_s) = harness::run_adaptive(&mut bench, cfg);
    harness::print_histogram(
        bench.name(),
        iterations,
        inner,
        duration_s,
        &hist,
        cfg.overhead,
    );
}

